      el.style.setProperty('--fx',rnd(10,70).toFixed(0)+'%');el.style.setProperty('--fr',rnd(-30,30).toFixed(0)+'deg');
      el.style.setProperty('--br',rnd(1,3).toFixed(1)+'px '+rnd(1,4).toFixed(1)+'px '+rnd(1,3).toFixed(1)+'px '+rnd(2,5).toFixed(1)+'px');
      el.style.zIndex=++z;
      el.innerHTML='<div class="ph" style="aspect-ratio:'+im.w+'/'+im.h+'"><i style="background-image:url('+im.src+')"></i></div>';
      stage.appendChild(el);
