    var a=i/N*Math.PI*2+R(-.12,.12),r=R(39,48);
    out.push({a:a,p:[50+r*Math.cos(a),50+r*Math.sin(a)]});
    var a2=a+R(-.2,.2),r2=r*R(.4,.58);
