    cr+='<line x1="'+A[0].toFixed(1)+'" y1="'+A[1].toFixed(1)+'" x2="'+B[0].toFixed(1)+'" y2="'+B[1].toFixed(1)+'" stroke="rgba(70,58,40,.13)" stroke-width=".3"/>'+
        '<line x1="'+(A[0]+.45).toFixed(1)+'" y1="'+(A[1]-.45).toFixed(1)+'" x2="'+(B[0]+.45).toFixed(1)+'" y2="'+(B[1]-.45).toFixed(1)+'" stroke="rgba(255,255,255,.5)" stroke-width=".25"/>';
